import pandas as pd
import numpy as np
from shapely import wkb, wkt
from shapely.geometry.base import BaseGeometry
from shapely.ops import transform as shp_transform
from pyproj import Transformer

# Reuse staged dataframes and CRS metadata; do not assign the required output variable.
analysis_educational_centroid_distance_status = "started"

def _find_geom_col(df):
    candidates = [c for c in df.columns if "geom" in c.lower() or c.lower() in ("geometry", "coordinate", "centroid")]
    if not candidates:
        raise ValueError("No geometry-like column found in staged dataframe.")
    return candidates[0]

def _to_shapely_geom(v):
    if v is None or (isinstance(v, float) and np.isnan(v)):
        return None
    if isinstance(v, BaseGeometry):
        return v
    if isinstance(v, memoryview):
        v = v.tobytes()
    if isinstance(v, (bytes, bytearray)):
        return wkb.loads(bytes(v))
    if isinstance(v, str):
        s = v.strip()
        try:
            if all(ch in "0123456789ABCDEFabcdef" for ch in s[:20]) and len(s) >= 40:
                return wkb.loads(bytes.fromhex(s))
        except Exception:
            pass
        return wkt.loads(s)
    try:
        if hasattr(v, "data"):
            return wkb.loads(bytes(v.data))
        if hasattr(v, "desc"):
            return wkb.loads(bytes.fromhex(v.desc))
    except Exception:
        pass
    raise TypeError(f"Unsupported geometry value type: {type(v)}")

analysis_school_geom_col = _find_geom_col(educational_sensitive_area_polygons_df)
analysis_station_geom_col = _find_geom_col(roadside_station_geometries_df)

analysis_school_id_col = "id" if "id" in educational_sensitive_area_polygons_df.columns else educational_sensitive_area_polygons_df.index.name
analysis_station_id_col = "id" if "id" in roadside_station_geometries_df.columns else ("station_id" if "station_id" in roadside_station_geometries_df.columns else None)

analysis_school_geoms_source = educational_sensitive_area_polygons_df[analysis_school_geom_col].map(_to_shapely_geom)
analysis_station_geoms_source = roadside_station_geometries_df[analysis_station_geom_col].map(_to_shapely_geom)

analysis_src_epsg = int(spatial_crs_source_epsg)
analysis_metric_epsg = int(spatial_crs_metric_epsg)
analysis_to_metric_transformer = Transformer.from_crs(f"EPSG:{analysis_src_epsg}", f"EPSG:{analysis_metric_epsg}", always_xy=True)

analysis_school_geoms_metric = analysis_school_geoms_source.map(lambda g: shp_transform(analysis_to_metric_transformer.transform, g) if g is not None and not g.is_empty else None)
analysis_station_geoms_metric = analysis_station_geoms_source.map(lambda g: shp_transform(analysis_to_metric_transformer.transform, g) if g is not None and not g.is_empty else None)

analysis_school_centroids_metric = analysis_school_geoms_metric.map(lambda g: g.centroid if g is not None and not g.is_empty else None)
analysis_valid_station_geoms_metric = [g for g in analysis_station_geoms_metric if g is not None and not g.is_empty]

if analysis_station_id_col is not None and set(roadside_station_ids_requested).issubset(set(roadside_station_geometries_df[analysis_station_id_col].astype(int).tolist())):
    analysis_station_ids_used_for_5km = [int(x) for x in roadside_station_ids_requested]
else:
    analysis_station_ids_used_for_5km = [14, 16, 17]

analysis_school_min_distance_to_roadside_m = []
analysis_school_within_roadside_5km_flags = []
for c in analysis_school_centroids_metric:
    if c is None or c.is_empty or not analysis_valid_station_geoms_metric:
        analysis_school_min_distance_to_roadside_m.append(np.nan)
        analysis_school_within_roadside_5km_flags.append(False)
    else:
        d = min(c.distance(sg) for sg in analysis_valid_station_geoms_metric)
        analysis_school_min_distance_to_roadside_m.append(float(d))
        analysis_school_within_roadside_5km_flags.append(bool(d <= 5000.0))

analysis_school_centroid_distance_df = pd.DataFrame({
    "source_index": educational_sensitive_area_polygons_df.index,
    "institution_id": educational_sensitive_area_polygons_df["id"].values if "id" in educational_sensitive_area_polygons_df.columns else educational_sensitive_area_polygons_df.index.values,
    "centroid_min_distance_m": analysis_school_min_distance_to_roadside_m,
    "centroid_within_5000m_any_roadside_station": analysis_school_within_roadside_5km_flags
})

analysis_schools_roadside_5km_distinct_count = int(
    analysis_school_centroid_distance_df.loc[
        analysis_school_centroid_distance_df["centroid_within_5000m_any_roadside_station"],
        "institution_id"
    ].drop_duplicates().shape[0]
)

analysis_educational_centroid_distance_summary = {
    "educational_institution_polygons_input": int(len(educational_sensitive_area_polygons_df)),
    "valid_educational_geometries": int(sum(g is not None and not g.is_empty for g in analysis_school_geoms_source)),
    "roadside_stations_input": int(len(roadside_station_geometries_df)),
    "valid_roadside_station_geometries": int(len(analysis_valid_station_geoms_metric)),
    "stations_used": analysis_station_ids_used_for_5km,
    "distinct_centroid_within_5000m_count": analysis_schools_roadside_5km_distinct_count
}
analysis_educational_centroid_distance_status = "completed"

print("Centroid-distance analysis summary:", analysis_educational_centroid_distance_summary)
